"""Renderers for usage stats lines distilled for benchmark use."""
from __future__ import annotations
from collections.abc import Mapping
from typing import Any

def _finite_number(value):
    if isinstance(value, bool) or not isinstance(value, (int, float)):
        return None
    number = float(value)
    if number != number or number in (float("inf"), float("-inf")):
        return None
    return number

def render_elapsed(events):
    if not events:
        return ""
    elapsed = None
    for event in events:
        if not isinstance(event, Mapping) or event.get("kind") != "usage_event":
            continue
        payload = event.get("payload")
        if not isinstance(payload, Mapping):
            continue
        seconds = _finite_number(payload.get("latency_s"))
        if seconds is not None and seconds >= 0:
            elapsed = seconds
    if elapsed is None:
        return ""
    return f"elapsed={elapsed:.1f}s"

def render_tokens_per_s(events):
    rate = None
    for event in events:
        if not isinstance(event, Mapping):
            continue
        if event.get("kind") != "usage_event":
            continue
        payload = event.get("payload")
        if not isinstance(payload, Mapping):
            continue
        latency = _finite_number(payload.get("latency_s"))
        if latency is None or latency <= 0:
            continue
        usage = payload.get("usage")
        if not isinstance(usage, Mapping):
            continue
        tokens = _finite_number(usage.get("output_tokens"))
        if tokens is None:
            tokens = _finite_number(usage.get("completion_tokens"))
        if tokens is None or tokens < 0:
            continue
        rate = tokens / latency
    if rate is None:
        return ""
    return f"tokens/s={rate:.1f}"

